// Career profiles — the richer per-job data behind the Career Explorer,
// keyed by career id.
//
// NUMBERS from the U.S. Bureau of Labor Statistics:
//  - payLow/payHigh (10th/90th-pct annual), hourly equivalents, and numJobs:
//    OEWS May 2025, fetched by SOC and verified against each median.
//  - annualOpenings: BLS Employment Projections, 2024–34 annual average.
// PROSE describes the occupation from the BLS Occupational Outlook Handbook;
// `related` cross-links career ids. Re-verify on refresh (see lib/freshness).

import { CAREER_ADDITION_DETAILS } from "./careerAdditions.ts";

export interface CareerDetail {
  soc: string;
  payLow?: number;
  payHigh?: number;
  hourlyPayLow?: number;
  hourlyMedian?: number;
  hourlyPayHigh?: number;
  numJobs?: number;
  /** Projected annual openings, 2024–34 average (BLS Employment Projections). */
  annualOpenings?: number;
  selfEmployedPercent?: number;
  workExperience?: string;
  onJobTraining?: string;
  oohUrl?: string;
  whatTheyDo: string;
  workSetting: string;
  hours: string;
  skills: string[];
  license?: string;
  related: string[];
}

